import{_ as n,C as s,o as i,c,aj as r,E as o,j as d,a}from"./framework.js";const f=JSON.parse('{"title":"Action Hooks | Settings | Admin CMS","description":"Action Hooks fire rules before and after backend resource operations such as create, update, and delete, for auditing, synchronization, notifications, or business validation before a…","frontmatter":{"title":"Action Hooks | Settings | Admin CMS","description":"Action Hooks fire rules before and after backend resource operations such as create, update, and delete, for auditing, synchronization, notifications, or business validation before a…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/settings/action-hooks.html"}]]},"headers":[],"relativePath":"cms/settings/action-hooks.md","filePath":"en/cms/settings/action-hooks.md","lastUpdated":1783042246000}'),l={name:"cms/settings/action-hooks.md"};function h(g,t,u,p,b,m){const e=s("DocImage");return i(),c("div",null,[t[0]||(t[0]=r('<h1 id="action-hooks" tabindex="-1">Action Hooks <a class="header-anchor" href="#action-hooks" aria-label="Permalink to &quot;Action Hooks&quot;">​</a></h1><blockquote><p>Menu: <strong>Settings -&gt; Action Hooks</strong> (advanced menu) List: <code>/_Admin/system/backend-events?SiteId={siteGuid}</code> Edit: <code>/_Admin/system/backend-events/edit?SiteId={siteGuid}&amp;name={eventName}&amp;display={displayName}</code></p></blockquote><p><strong>Action Hooks</strong> fire rules before and after backend resource operations such as <strong>create, update, and delete</strong>, for auditing, synchronization, notifications, or business validation before a resource is saved. They map to server-side <code>BackendRule</code> + <code>BackendEvent</code>. Rules run only when the site-level <strong><code>enableBackendEvents</code></strong> switch is on.</p><div class="tip custom-block"><p class="custom-block-title">Permissions</p><table tabindex="0"><thead><tr><th>Action</th><th>Permission</th></tr></thead><tbody><tr><td>View the hook list and edit page</td><td><code>backendEvents</code></td></tr><tr><td>Toggle <strong>Hook On / Off</strong> in the top-right</td><td><code>site·edit</code> (saves site field <code>enableBackendEvents</code>)</td></tr><tr><td><strong>New Hook</strong>, edit rules, and <strong>Save</strong></td><td><code>backendEvents·edit</code></td></tr><tr><td>Multi-select <strong>Delete</strong> all rules under an event</td><td><code>backendEvents·edit</code></td></tr></tbody></table><p>In the current UI, <strong>New Hook</strong> and <strong>Save</strong> on the edit page still check <code>frontEvents·edit</code>; verify that permission when assigning roles.</p></div><div class="info custom-block"><p class="custom-block-title">Master switch</p><p>Besides <strong>Hook On</strong> on this page, <strong>Action Hooks</strong> (<code>enableBackendEvents</code>) in <a href="./basic/advanced.html#constraints-and-other-switches">Basic Settings · Advanced</a> must be on. Both controls edit the same site field; if either is off, no action hooks run.</p></div><div class="warning custom-block"><p class="custom-block-title">Distinction from Request Hooks</p><table tabindex="0"><thead><tr><th></th><th><a href="./request-hooks.html">Request Hooks</a></th><th><strong>Action Hooks (this page)</strong></th></tr></thead><tbody><tr><td>When they run</td><td>Front-end <strong>HTTP requests</strong> (Route / Page / View)</td><td>Backend <strong>resource operations</strong> (create / update / delete, etc.)</td></tr><tr><td>Path</td><td><code>/system/front-events</code></td><td><code>/system/backend-events</code></td></tr><tr><td>Rule resource</td><td><code>BusinessRule</code></td><td><code>BackendRule</code></td></tr><tr><td>Master switch</td><td><code>enableFrontEvents</code></td><td><code>enableBackendEvents</code></td></tr></tbody></table></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>, enable <strong>Settings -&gt; Action Hooks</strong>.</li><li>Open <strong>Settings -&gt; Action Hooks</strong> in the left sidebar.</li></ol>',8)),o(e,{src:"/cms/settings/settings-action-hooks-overview.png",alt:"Action hooks list",width:"1120"}),t[1]||(t[1]=r('<h2 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Description</th></tr></thead><tbody><tr><td><strong>New Hook</strong></td><td>Opens <a href="#new-hook">hook type picker</a> (event types already configured are hidden)</td></tr><tr><td><strong>Hook On / Off</strong></td><td><code>enableBackendEvents</code>; toggling <strong>saves the site immediately</strong> (<code>saveSite</code>)</td></tr><tr><td>Status text</td><td>When on, shows “Hook On” (blue); when off, gray “Hook Off”</td></tr></tbody></table>',2)),o(e,{src:"/cms/settings/settings-action-hooks-toolbar.png",alt:"Action hooks toolbar",width:"1120"}),t[2]||(t[2]=r('<h2 id="hook-list" tabindex="-1">Hook List <a class="header-anchor" href="#hook-list" aria-label="Permalink to &quot;Hook List&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td>Localized display of event <code>name</code> (e.g. PageCreated → “Page created”; wording follows login language)</td></tr><tr><td><strong>Rule count</strong></td><td>Number of saved rules for that event</td></tr><tr><td><strong>Edit</strong></td><td>Opens <a href="#rule-edit-page">rule edit page</a></td></tr></tbody></table><p>Multi-select <strong>Delete</strong> removes <strong>all</strong> rules for the selected event types (<code>BackendRule/DeleteEvents</code>), not individual rules.</p>',3)),o(e,{src:"/cms/settings/settings-action-hooks-list.png",alt:"Action hooks list",width:"1120"}),t[3]||(t[3]=d("h2",{id:"new-hook",tabindex:"-1"},[a("New Hook "),d("a",{class:"header-anchor",href:"#new-hook","aria-label":'Permalink to "New Hook"'},"​")],-1)),t[4]||(t[4]=d("p",null,[a("Click "),d("strong",null,"New Hook"),a(" to open the "),d("strong",null,"Hook list"),a(", grouped by resource category. Click a type to open the edit page (the row may not appear until rules are saved).")],-1)),o(e,{src:"/cms/settings/settings-action-hooks-event-picker.png",alt:"Hook type picker",width:"1120"}),t[5]||(t[5]=r('<h3 id="available-event-types" tabindex="-1">Available Event Types <a class="header-anchor" href="#available-event-types" aria-label="Permalink to &quot;Available Event Types&quot;">​</a></h3><p>The hook list is grouped by resource. Display names are localized via server <code>Hardcoded</code>; use <code>BackendRule/EventList</code> as the source of truth.</p><h4 id="image-events" tabindex="-1">Image Events <a class="header-anchor" href="#image-events" aria-label="Permalink to &quot;Image Events&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Timing</th><th>Event name (<code>name</code>)</th></tr></thead><tbody><tr><td>Before / after upload</td><td><code>ImageUploading</code> / <code>ImageUpload</code></td></tr><tr><td>Before / after update</td><td><code>ImageUpdating</code> / <code>ImageUpdated</code></td></tr><tr><td>Before / after delete</td><td><code>ImageDeleting</code> / <code>ImageDelete</code></td></tr></tbody></table><h4 id="general-resource-events" tabindex="-1">General Resource Events <a class="header-anchor" href="#general-resource-events" aria-label="Permalink to &quot;General Resource Events&quot;">​</a></h4><p>Each resource follows <strong>resource prefix + timing suffix</strong>, e.g. <code>PageCreating</code>, <code>ContentUpdated</code>.</p><table tabindex="0"><thead><tr><th>Backend group</th><th><code>name</code> prefix</th></tr></thead><tbody><tr><td>Page</td><td><code>Page</code></td></tr><tr><td>View</td><td><code>View</code></td></tr><tr><td>Layout</td><td><code>Layout</code></td></tr><tr><td>Code</td><td><code>Code</code></td></tr><tr><td>Menu</td><td><code>Menu</code></td></tr><tr><td>HTML block</td><td><code>HtmlBlock</code></td></tr><tr><td>Content</td><td><code>Content</code></td></tr><tr><td>Label</td><td><code>Label</code></td></tr><tr><td>Script</td><td><code>Script</code></td></tr><tr><td>Style</td><td><code>Style</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Operation timing</th><th><code>name</code> suffix</th><th>Example</th></tr></thead><tbody><tr><td>Before / after create</td><td><code>Creating</code> / <code>Created</code></td><td><code>PageCreating</code> / <code>PageCreated</code></td></tr><tr><td>Before / after update</td><td><code>Updating</code> / <code>Updated</code></td><td><code>ContentUpdating</code> / <code>ContentUpdated</code></td></tr><tr><td>Before / after delete</td><td><code>Deleting</code> / <code>Deleted</code></td><td><code>ScriptDeleting</code> / <code>ScriptDeleted</code></td></tr></tbody></table><h4 id="commerce-events" tabindex="-1">Commerce Events <a class="header-anchor" href="#commerce-events" aria-label="Permalink to &quot;Commerce Events&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Backend group</th><th>Event name (<code>name</code>)</th><th>Typical timing</th></tr></thead><tbody><tr><td>Product</td><td><code>ProductCreating</code> / <code>ProductCreated</code></td><td>Before / after product create</td></tr><tr><td>Product</td><td><code>ProductUpdating</code> / <code>ProductUpdated</code></td><td>Before / after product update</td></tr><tr><td>Product</td><td><code>ProductDeleting</code> / <code>ProductDeleted</code></td><td>Before / after product delete</td></tr><tr><td>Product</td><td><code>ProductCopied</code></td><td>After product copy</td></tr><tr><td>Product category</td><td><code>ProductCategoryCreating</code> / <code>ProductCategoryCreated</code></td><td>Before / after category create</td></tr><tr><td>Product category</td><td><code>ProductCategoryUpdating</code> / <code>ProductCategoryUpdated</code></td><td>Before / after category update</td></tr><tr><td>Product category</td><td><code>ProductCategoryDeleting</code> / <code>ProductCategoryDeleted</code></td><td>Before / after category delete</td></tr><tr><td>Order</td><td><code>OrderConfirmed</code></td><td>Order confirmed</td></tr><tr><td>Order</td><td><code>OrderDelivered</code></td><td>Order shipped</td></tr><tr><td>Order</td><td><code>OrderCancelled</code></td><td>Order cancelled</td></tr></tbody></table><h2 id="rule-edit-page" tabindex="-1">Rule Edit Page <a class="header-anchor" href="#rule-edit-page" aria-label="Permalink to &quot;Rule Edit Page&quot;">​</a></h2><p>Breadcrumb: <strong>Action Hooks -&gt; {event display name}</strong>. No sidebar menu item; deep links require <code>name</code> (required) and <code>display</code> (breadcrumb).</p>',12)),o(e,{src:"/cms/settings/settings-action-hooks-edit.png",alt:"Rule edit page",width:"1120"}),t[6]||(t[6]=r('<h3 id="new-rule" tabindex="-1">New Rule <a class="header-anchor" href="#new-rule" aria-label="Permalink to &quot;New Rule&quot;">​</a></h3><p><strong>New Rule</strong> dropdown on the toolbar:</p><table tabindex="0"><thead><tr><th>Type</th><th>Value</th><th>Structure</th></tr></thead><tbody><tr><td><strong>IF-ELSE-THEN</strong></td><td><code>IF-ELSE-THEN</code></td><td>Condition <strong>IF</strong> + branches <strong>THEN</strong> / <strong>ELSE</strong> (nested rules allowed)</td></tr><tr><td><strong>DO</strong></td><td><code>DO</code></td><td>Run one or more <strong>Code</strong> blocks in sequence</td></tr></tbody></table><p>If there are no rules when you open the edit page, one <strong>IF-ELSE-THEN</strong> rule is added by default.</p><h3 id="rule-cards" tabindex="-1">Rule Cards <a class="header-anchor" href="#rule-cards" aria-label="Permalink to &quot;Rule Cards&quot;">​</a></h3><ul><li>Drag handle on the card <strong>title bar</strong> to reorder rules for the same event.</li><li><strong>Delete</strong> on the title bar removes the whole rule.</li></ul><h4 id="if-else-then" tabindex="-1">IF-ELSE-THEN <a class="header-anchor" href="#if-else-then" aria-label="Permalink to &quot;IF-ELSE-THEN&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Area</th><th>Description</th></tr></thead><tbody><tr><td><strong>IF</strong></td><td>Click the label to open <a href="#edit-conditions">condition editor</a>; multiple conditions shown joined with <code>&amp;&amp;</code></td></tr><tr><td><strong>THEN</strong> / <strong>ELSE</strong></td><td>Nested rule lists; add more IF-ELSE-THEN or DO rules</td></tr></tbody></table><h4 id="do" tabindex="-1">DO <a class="header-anchor" href="#do" aria-label="Permalink to &quot;DO&quot;">​</a></h4><p>Lists Code snippet summaries; <strong>+</strong> adds Code, pencil edits. Code is written in Monaco as KScript (<code>language: typescript</code>, KScript mode). See related links at the end for script objects and APIs.</p>',10)),o(e,{src:"/cms/settings/settings-action-hooks-code-dialog.png",alt:"Code edit dialog",width:"1120"}),t[7]||(t[7]=d("h3",{id:"edit-conditions",tabindex:"-1"},[a("Edit Conditions "),d("a",{class:"header-anchor",href:"#edit-conditions","aria-label":'Permalink to "Edit Conditions"'},"​")],-1)),o(e,{src:"/cms/settings/settings-action-hooks-condition-dialog.png",alt:"Edit conditions",width:"1120"}),t[8]||(t[8]=r('<table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Left value</strong></td><td>Fields available for the current event (<code>BackendRule/ConditionOption</code>), e.g. resource <code>Name</code>, <code>Body</code>, <code>Url</code>, content <code>FolderName</code>, product <code>Title</code>, etc.</td></tr><tr><td><strong>Operator</strong></td><td>Varies by left-value type (e.g. <code>=</code>, <code>!=</code>, <code>Contains</code>, <code>&gt;</code>, etc.)</td></tr><tr><td><strong>Right value</strong></td><td>Comparison constant</td></tr></tbody></table><p>Use <strong>+</strong> to add condition rows; confirm writes back to the rule <code>if</code> array. Evaluation runs at runtime via <code>ConditionManager.Evaluate</code>.</p><h3 id="save-and-leave" tabindex="-1">Save and Leave <a class="header-anchor" href="#save-and-leave" aria-label="Permalink to &quot;Save and Leave&quot;">​</a></h3><p>Bottom <strong>KBottomBar</strong>: <strong>Back</strong> returns to the list; <strong>Save</strong> calls <code>BackendRule/post</code> (<code>eventName</code> + <code>rules</code>). Unsaved changes prompt before leaving (<code>useSaveTip</code>).</p><h2 id="execution-order-concept" tabindex="-1">Execution Order (Concept) <a class="header-anchor" href="#execution-order-concept" aria-label="Permalink to &quot;Execution Order (Concept)&quot;">​</a></h2><ol><li>Site <code>enableBackendEvents</code> is true.</li><li>A backend resource operation fires the matching BackendEvent (e.g. <code>PageCreating</code>, <code>ContentUpdated</code>).</li><li>Rules for that event run in list order; IF-ELSE-THEN evaluates conditions then THEN/ELSE; DO runs Code in sequence.</li></ol><p>Execution is handled by the site&#39;s backend action hook engine, in the order configured on this page.</p><h2 id="typical-workflow" tabindex="-1">Typical Workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical Workflow&quot;">​</a></h2><ol><li>Confirm <a href="./basic/advanced.html">Advanced tab</a> and <strong>Hook On</strong> on this page.</li><li><strong>New Hook</strong> → pick target resource and timing, e.g. <strong>ContentUpdated</strong>.</li><li>Add <strong>IF-ELSE-THEN</strong> to filter resource fields, or <strong>DO</strong> for backend actions.</li><li><strong>Save</strong>, then create, update, or delete the resource in the admin to verify.</li><li>On collaborative export, hooks map to <strong>BackendRule</strong> resources in the site package.</li></ol><h2 id="cms-vs-api" tabindex="-1">CMS vs API <a class="header-anchor" href="#cms-vs-api" aria-label="Permalink to &quot;CMS vs API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>CMS</th><th>API / Template Engine</th></tr></thead><tbody><tr><td>Which backend operations trigger rules</td><td>This page: hook type picker and rule save</td><td>—</td></tr><tr><td>Script actions inside rules</td><td>Entry via Code dialog only</td><td><a href="./../development/code.html">Development -&gt; Code</a>, <a href="/kb-docs/api/site/code.html">k.site Code API</a></td></tr><tr><td>Content data after content save</td><td>Content events on this page</td><td><a href="/kb-docs/api/content/">k.content</a></td></tr><tr><td>Commerce data after product/order events</td><td>Product / Order events on this page</td><td><a href="/kb-docs/api/commerce/commerce.html">k.commerce</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./">Settings overview</a></td><td>Menu and sub-routes</td></tr><tr><td><a href="./basic/advanced.html">Basic Settings · Advanced</a></td><td><code>enableBackendEvents</code></td></tr><tr><td><a href="./request-hooks.html">Request Hooks</a></td><td>Front-end request lifecycle events</td></tr><tr><td><a href="./../development/code.html">Development -&gt; Code</a></td><td>KScript code resource entry</td></tr><tr><td><a href="/kb-docs/api/content/">Content API</a></td><td>Content read/write</td></tr><tr><td><a href="/kb-docs/api/commerce/commerce.html">Commerce API</a></td><td>Product, category, order APIs</td></tr></tbody></table>',13))])}const v=n(l,[["render",h]]);export{f as __pageData,v as default};
